import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { CoolingScene } from './scene';
import { direct, type StationState } from './director';

let root: HTMLElement | null = null;
let scene: CoolingScene | null = null;
let state: StationState = { progress: 0, density: 72, water: 58, mode: 'manual' };
let scrollRange = 1;
let scrollListener: (() => void) | null = null;
let wheelListener: (() => void) | null = null;
let demoTimer: number | null = null;

function clamp(value: number): number {
  return Math.max(0, Math.min(1, value));
}

function takeControl(mode: StationState['mode']): void {
  state.mode = mode;
  if (demoTimer !== null) {
    window.clearTimeout(demoTimer);
    demoTimer = null;
  }
}

function updateInterface(): void {
  if (!root) return;
  const noonHeat = Math.exp(-Math.pow((state.progress - 0.55) / 0.23, 2));
  const shade = Math.round(22 + state.density * 0.5 + state.water * 0.05);
  const temp = Math.round(42 + noonHeat * 4 - state.density * 0.11 - state.water * 0.035);
  const phase = state.progress < 0.28 ? '08:10 · 清晨基线' : state.progress < 0.72 ? '12:40 · 正午观察' : '17:20 · 浇灌后';
  root.querySelector<HTMLElement>('[data-phase]')!.textContent = phase;
  root.querySelector<HTMLElement>('[data-shade]')!.textContent = `${shade}%`;
  root.querySelector<HTMLElement>('[data-temp]')!.textContent = `${temp}°C`;
  root.querySelector<HTMLElement>('[data-transpire]')!.textContent = state.water > 50
    ? '叶面蒸腾与地面树荫共同降低体感温度。'
    : '当前补水不足，正午蒸腾效率正在下降。';
  const demo = root.querySelector<HTMLButtonElement>('[data-demo]')!;
  demo.textContent = state.mode === 'demo' ? '暂停演示' : '播放自动演示';
  demo.setAttribute('aria-pressed', String(state.mode === 'demo'));
  root.dataset.driveMode = state.mode;
  const marker = root.querySelector<HTMLElement>('[data-signal-driver-progress]')!;
  marker.dataset.progress = state.progress.toFixed(3);
  marker.setAttribute('aria-valuenow', String(Math.round(state.progress * 100)));
  root.style.setProperty('--progress', state.progress.toFixed(3));
  root.style.setProperty('--scene-pan', `${Math.round((state.progress - 0.5) * -22)}px`);
  root.style.setProperty('--canopy', (state.density / 100).toFixed(3));
  root.style.setProperty('--wet', (state.water / 100).toFixed(3));
  root.style.setProperty('--saturation', `${Math.round(84 + state.density * 0.18)}%`);
  root.style.setProperty('--brightness', `${Math.round(76 + state.water * 0.08)}%`);
}

startExperience(defineExperience({
  mount(context) {
    root = document.createElement('main');
    root.className = `station${context.reducedMotion ? ' reduced' : ''}`;
    root.setAttribute('data-signal-shared-driver', '');
    root.setAttribute('data-drive-mode', state.mode);
    context.canvas.setAttribute('data-signal-visual-anchor', '');
    root.innerHTML = `
      <div class="driver-progress" data-signal-driver-progress role="progressbar" aria-label="一天中的观察进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span></span></div>
      <header class="masthead"><a class="identity" href="#top">CANOPY / 01</a><span>街道微气候观察计划</span><button class="demo" data-demo data-signal-demo-control aria-pressed="false">播放自动演示</button></header>
      <section class="hero" id="top">
        <div class="hero-copy">
          <p class="eyebrow">一棵成熟行道树 · 一天的实测推演</p>
          <h1>让树荫<br>成为街道<br>基础设施</h1>
          <p class="intro">滚动经过清晨、正午与浇灌后，观察同一段路面如何获得可以感知的阴凉。</p>
          <button class="start" data-jump>进入正午观察 <span>↓</span></button>
        </div>
        <p class="photo-note">影像为场景表达 · 温度为方案估算</p>
      </section>
      <section class="workspace" aria-label="降温方案工作区">
        <div class="station-card">
          <div class="card-head"><span data-phase>08:10 · 清晨基线</span><span class="live"><i></i>方案联动中</span></div>
          <div class="metrics" data-signal-primary-result>
            <div><small>预计树荫覆盖</small><strong data-shade>—</strong></div>
            <div><small>路面温度 <em>估算</em></small><strong data-temp>—</strong></div>
          </div>
          <p class="transpire" data-transpire aria-live="polite">—</p>
          <label>树冠密度 <output data-density>72%</output><input data-density-input data-signal-primary-control type="range" min="25" max="100" value="72" aria-label="树冠密度"></label>
          <label>补水水平 <output data-water>58%</output><input data-water-input data-signal-primary-control type="range" min="0" max="100" value="58" aria-label="补水水平"></label>
          <div class="routes" aria-label="观察时间"><button data-route="0">08:10</button><button data-route=".56">12:40</button><button data-route="1">17:20</button></div>
        </div>
        <aside class="field-note"><span>01</span><p>树荫不是装饰。冠幅、供水与一天中的太阳位置，共同决定路面是否适合停留。</p></aside>
      </section>
      <section class="closing">
        <div><p class="eyebrow">当前方案 · 可继续讨论</p><h2>把阴凉留在<br>行人需要的地方</h2></div>
        <div class="closing-action"><p>保存当前冠幅与补水参数，形成一份可用于街道绿化讨论的降温建议。</p><button class="save" data-save data-signal-primary-action>保存这次降温方案</button><p class="saved" aria-live="polite"></p></div>
      </section>`;
    context.container.appendChild(root);
    scene = new CoolingScene(context.canvas, context.viewport, context.quality);

    const density = root.querySelector<HTMLInputElement>('[data-density-input]')!;
    const water = root.querySelector<HTMLInputElement>('[data-water-input]')!;
    density.addEventListener('input', () => { state.density = Number(density.value); takeControl('manual'); });
    water.addEventListener('input', () => { state.water = Number(water.value); takeControl('manual'); });
    root.querySelectorAll<HTMLButtonElement>('[data-route]').forEach((button) => button.addEventListener('click', () => {
      takeControl('manual');
      state.progress = Number(button.dataset.route);
      window.scrollTo({ top: state.progress * scrollRange, behavior: context.reducedMotion ? 'auto' : 'smooth' });
    }));
    root.querySelector<HTMLButtonElement>('[data-demo]')!.addEventListener('click', () => {
      takeControl(state.mode === 'demo' ? 'paused' : 'demo');
    });
    root.querySelector<HTMLButtonElement>('[data-jump]')!.addEventListener('click', () => {
      takeControl('scroll');
      root?.querySelector('.workspace')?.scrollIntoView({ behavior: context.reducedMotion ? 'auto' : 'smooth' });
    });
    root.querySelector<HTMLButtonElement>('[data-save]')!.addEventListener('click', () => {
      root?.querySelector<HTMLElement>('.saved')!.replaceChildren('已保存：树冠密度、补水水平与当前路温估算。');
    });
    wheelListener = () => takeControl('scroll');
    scrollListener = () => {
      scrollRange = Math.max(1, document.documentElement.scrollHeight - innerHeight);
      if (state.mode === 'scroll') state.progress = clamp(scrollY / scrollRange);
    };
    addEventListener('wheel', wheelListener, { passive: true });
    addEventListener('scroll', scrollListener, { passive: true });
    scrollListener();
    updateInterface();
    if (!context.reducedMotion) demoTimer = window.setTimeout(() => {
      if (state.mode === 'manual') state.mode = 'demo';
      demoTimer = null;
    }, 1400);
  },
  update(frame) {
    if (!scene || !root) return;
    if (state.mode === 'demo' && !frame.reducedMotion) state.progress = (frame.elapsed * 0.052) % 1;
    if (frame.reducedMotion && state.mode === 'demo') state.progress = 0.56;
    const view = direct(state, frame.pointer, frame.elapsed, frame.reducedMotion);
    scene.render(view, frame.viewport);
    root.querySelector<HTMLOutputElement>('[data-density]')!.value = `${state.density}%`;
    root.querySelector<HTMLOutputElement>('[data-water]')!.value = `${state.water}%`;
    updateInterface();
  },
  resize(viewport) { scene?.resize(viewport); },
  dispose() {
    if (demoTimer !== null) window.clearTimeout(demoTimer);
    if (scrollListener) removeEventListener('scroll', scrollListener);
    if (wheelListener) removeEventListener('wheel', wheelListener);
    document.querySelector('canvas[data-signal-visual-anchor]')?.removeAttribute('data-signal-visual-anchor');
    scene?.dispose();
    root?.remove();
    root = null;
    scene = null;
  },
}));

export type StationState = {
  progress: number;
  density: number;
  water: number;
  mode: 'demo' | 'scroll' | 'manual' | 'paused';
};

export type DirectedState = {
  time: number;
  canopy: number;
  wet: number;
  heat: number;
  breeze: number;
};

export function direct(
  state: StationState,
  pointer: { x: number; y: number },
  elapsed: number,
  reducedMotion: boolean,
): DirectedState {
  const time = Math.max(0, Math.min(1, state.progress));
  const noon = Math.exp(-Math.pow((time - 0.55) / 0.23, 2));
  const afterWater = Math.max(0, (time - 0.62) / 0.38) * (state.water / 100);
  return {
    time,
    canopy: state.density / 100,
    wet: afterWater,
    heat: noon * (1 - state.density / 150),
    breeze: reducedMotion ? 0 : pointer.x * 0.025 + Math.sin(elapsed * 0.55) * 0.012,
  };
}

import * as THREE from 'three';
import type { DirectedState } from './director';

type Viewport = { width: number; height: number; dpr: number };

function radialTexture(rgb: string): THREE.CanvasTexture {
  const source = document.createElement('canvas');
  source.width = 256;
  source.height = 256;
  const context = source.getContext('2d')!;
  const gradient = context.createRadialGradient(128, 128, 8, 128, 128, 126);
  gradient.addColorStop(0, `rgba(${rgb},1)`);
  gradient.addColorStop(0.48, `rgba(${rgb},.5)`);
  gradient.addColorStop(1, `rgba(${rgb},0)`);
  context.fillStyle = gradient;
  context.fillRect(0, 0, 256, 256);
  const texture = new THREE.CanvasTexture(source);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

export class CoolingScene {
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10);
  private imageTexture: THREE.Texture;
  private imageMaterial: THREE.MeshBasicMaterial;
  private imagePlane: THREE.Mesh;
  private imageAspect = 16 / 9;
  private viewportAspect = 16 / 9;
  private shadeTexture = radialTexture('21,41,25');
  private wetTexture = radialTexture('104,150,150');
  private heatTexture = radialTexture('247,205,126');
  private shade: THREE.Sprite;
  private wet: THREE.Sprite;
  private heat: THREE.Sprite;

  constructor(canvas: HTMLCanvasElement, viewport: Viewport, quality: 'low' | 'balanced' | 'high') {
    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: quality === 'high' });
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.camera.position.z = 2;

    this.imageTexture = new THREE.TextureLoader().load('/creative-assets/r82-tree-canopy/street-canopy-hero-v1.png', (texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;
      this.imageAspect = texture.image.width / Math.max(1, texture.image.height);
      this.updateCover();
    });
    this.imageTexture.colorSpace = THREE.SRGBColorSpace;
    this.imageMaterial = new THREE.MeshBasicMaterial({ map: this.imageTexture, color: '#ffffff' });
    this.imagePlane = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.imageMaterial);
    this.imagePlane.position.z = -1;
    this.scene.add(this.imagePlane);

    this.shade = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.shadeTexture, transparent: true, depthWrite: false, opacity: 0.2 }));
    this.shade.position.set(0.22, -0.62, 0);
    this.shade.scale.set(1.8, 0.7, 1);
    this.scene.add(this.shade);

    this.wet = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.wetTexture, transparent: true, depthWrite: false, opacity: 0 }));
    this.wet.position.set(0.32, -0.72, 0.1);
    this.wet.scale.set(1.25, 0.34, 1);
    this.scene.add(this.wet);

    this.heat = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.heatTexture, transparent: true, depthWrite: false, opacity: 0 }));
    this.heat.position.set(-0.45, -0.26, 0.05);
    this.heat.scale.set(1.4, 1.15, 1);
    this.scene.add(this.heat);
    this.resize(viewport);
  }

  resize(viewport: Viewport): void {
    this.viewportAspect = viewport.width / Math.max(1, viewport.height);
    this.updateCover();
    this.renderer.setPixelRatio(Math.min(viewport.dpr, 1.6));
    this.renderer.setSize(viewport.width, viewport.height, false);
  }

  private updateCover(): void {
    if (!this.imageTexture) return;
    if (this.viewportAspect > this.imageAspect) {
      const visibleHeight = this.imageAspect / this.viewportAspect;
      this.imageTexture.repeat.set(1, visibleHeight);
      this.imageTexture.offset.set(0, (1 - visibleHeight) * 0.5);
    } else {
      const visibleWidth = this.viewportAspect / this.imageAspect;
      this.imageTexture.repeat.set(visibleWidth, 1);
      this.imageTexture.offset.set((1 - visibleWidth) * 0.5, 0);
    }
    this.imageTexture.needsUpdate = true;
  }

  render(state: DirectedState, viewport: Viewport): void {
    this.resize(viewport);
    const daylight = 0.78 + (1 - Math.abs(state.time - 0.5) * 2) * 0.19;
    const brightness = Math.max(0.68, Math.min(1, daylight - state.canopy * 0.09 + state.wet * 0.025));
    this.imageMaterial.color.setRGB(brightness * 0.98, brightness, brightness * 0.94);
    this.shade.position.x = 0.18 - state.time * 0.08 + state.breeze;
    this.shade.scale.set(1.35 + state.canopy * 0.72, 0.42 + state.canopy * 0.36, 1);
    (this.shade.material as THREE.SpriteMaterial).opacity = 0.08 + state.canopy * 0.25;
    (this.wet.material as THREE.SpriteMaterial).opacity = state.wet * 0.34;
    this.wet.scale.set(1.05 + state.wet * 0.45, 0.26 + state.wet * 0.16, 1);
    (this.heat.material as THREE.SpriteMaterial).opacity = state.heat * 0.13;
    this.renderer.render(this.scene, this.camera);
  }

  dispose(): void {
    [this.shade, this.wet, this.heat].forEach((sprite) => (sprite.material as THREE.SpriteMaterial).dispose());
    this.shadeTexture.dispose();
    this.wetTexture.dispose();
    this.heatTexture.dispose();
    this.imagePlane.geometry.dispose();
    this.imageMaterial.dispose();
    this.imageTexture.dispose();
    this.renderer.dispose();
  }
}

* { box-sizing: border-box; }
html, body { margin: 0; max-width: 100%; overflow-x: hidden; background: #18211a; color: #f4f1e7; font-family: Inter, ui-sans-serif, system-ui, "Microsoft YaHei", sans-serif; scroll-behavior: smooth; }
button, a, input { font: inherit; }
button, a { color: inherit; }
button:focus-visible, a:focus-visible, input:focus-visible { outline: 2px solid #d8ef9c; outline-offset: 4px; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; z-index: 2; pointer-events: none; }
.station { --progress: 0; --canopy: .72; --wet: .58; --scene-pan: 0px; --saturation: 97%; --brightness: 81%; min-height: 286vh; position: relative; isolation: isolate; background: transparent; }
.visual-field { position: fixed; inset: 0; z-index: 0; overflow: hidden; background: #203024; }
.visual-field:before { content: ""; position: absolute; inset: -2%; background-image: url('/creative-assets/r82-tree-canopy/street-canopy-hero-v1.png'); background-size: cover; background-position: 52% center; transform: translate3d(var(--scene-pan), 0, 0) scale(1.035); filter: saturate(var(--saturation)) brightness(var(--brightness)); transition: filter .35s ease, transform .8s cubic-bezier(.2,.7,.2,1); }
.visual-field:after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(11,20,13,.8) 0%, rgba(11,20,13,.56) 29%, rgba(11,20,13,.08) 62%, rgba(11,20,13,.28) 100%), linear-gradient(180deg, rgba(10,16,11,.42), transparent 28%, transparent 64%, rgba(8,13,9,.72)); }
.masthead { position: fixed; z-index: 8; top: 0; left: 0; right: 0; height: 76px; padding: 0 clamp(22px,4vw,64px); display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid rgba(255,255,255,.18); font-size: 11px; letter-spacing: .14em; text-transform: uppercase; background: linear-gradient(180deg,rgba(10,17,12,.55),transparent); backdrop-filter: blur(2px); }
.identity { text-decoration: none; font-weight: 750; letter-spacing: .08em; }
.masthead > span { color: rgba(255,255,255,.62); }
.demo { justify-self: end; border: 1px solid rgba(255,255,255,.34); background: rgba(12,20,14,.32); border-radius: 999px; padding: 8px 13px; cursor: pointer; backdrop-filter: blur(12px); }
.driver-progress { position: fixed; z-index: 9; left: 0; top: 0; width: 100%; height: 2px; background: rgba(255,255,255,.12); }
.driver-progress span { display: block; width: 100%; height: 100%; background: #d8ef9c; transform: scaleX(var(--progress)); transform-origin: left center; transition: transform .14s linear; }
.hero, .workspace, .closing { position: relative; z-index: 4; }
.hero { min-height: 105vh; padding: clamp(112px,16vh,170px) clamp(22px,7vw,110px) 12vh; display: flex; flex-direction: column; justify-content: center; }
.hero-copy { width: min(540px,88vw); text-shadow: 0 2px 30px rgba(0,0,0,.35); }
.eyebrow { margin: 0 0 22px; color: #d8ef9c; font-size: 11px; letter-spacing: .16em; text-transform: uppercase; }
.hero h1 { margin: 0; font-family: "Noto Serif SC", "Songti SC", serif; font-weight: 520; font-size: clamp(54px,7.2vw,112px); line-height: .92; letter-spacing: -.07em; }
.intro { max-width: 30em; margin: 28px 0 30px; color: rgba(255,255,255,.78); font-size: 16px; line-height: 1.75; }
.start, .save { border: 0; border-radius: 999px; padding: 13px 18px; background: #e6f3c0; color: #1d2a1e; font-weight: 680; cursor: pointer; box-shadow: 0 10px 26px rgba(10,20,12,.22); }
.start span { margin-left: 24px; }
.photo-note { position: absolute; right: 4vw; bottom: 5vh; margin: 0; font-size: 10px; letter-spacing: .12em; color: rgba(255,255,255,.58); writing-mode: vertical-rl; }
.workspace { min-height: 112vh; padding: 18vh clamp(22px,6vw,88px) 22vh; display: grid; grid-template-columns: minmax(180px,1fr) minmax(330px,480px); gap: 8vw; align-items: center; }
.station-card { grid-column: 2; background: rgba(241,239,228,.91); color: #243026; border: 1px solid rgba(255,255,255,.52); box-shadow: 0 30px 90px rgba(7,14,9,.26); padding: clamp(22px,3vw,38px); border-radius: 2px; backdrop-filter: blur(18px); }
.card-head { display: flex; justify-content: space-between; gap: 16px; padding-bottom: 18px; border-bottom: 1px solid rgba(35,48,38,.2); font-size: 11px; letter-spacing: .08em; }
.live { color: #587057; }
.live i { display: inline-block; width: 6px; height: 6px; margin-right: 7px; border-radius: 50%; background: #6fa266; box-shadow: 0 0 0 4px rgba(111,162,102,.15); }
.metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: rgba(35,48,38,.16); margin: 26px 0 14px; }
.metrics div { background: rgba(248,247,240,.8); padding: 18px; }
.metrics small { display: block; margin-bottom: 6px; color: #657066; font-size: 11px; }
.metrics em { font-style: normal; font-size: 9px; }
.metrics strong { font-family: "Iowan Old Style", "Times New Roman", serif; font-size: clamp(36px,4vw,56px); font-weight: 450; letter-spacing: -.05em; }
.transpire { min-height: 3em; margin: 14px 0 20px; color: #496349; font-size: 13px; line-height: 1.6; }
.station-card label { display: block; margin-top: 18px; font-size: 12px; letter-spacing: .04em; }
.station-card output { float: right; color: #365c38; font-weight: 700; }
input[type=range] { width: 100%; height: 20px; margin-top: 10px; accent-color: #4f7a4d; cursor: pointer; }
.routes { display: grid; grid-template-columns: repeat(3,1fr); gap: 7px; margin-top: 24px; }
.routes button { border: 1px solid rgba(35,48,38,.22); background: transparent; color: #334435; padding: 9px 8px; border-radius: 999px; font-size: 11px; cursor: pointer; }
.routes button:hover { background: #e0e9d1; }
.field-note { align-self: end; max-width: 330px; display: flex; gap: 20px; padding: 18px 0; border-top: 1px solid rgba(255,255,255,.3); color: rgba(255,255,255,.72); font-size: 13px; line-height: 1.65; }
.field-note span { color: #d8ef9c; font-family: serif; font-size: 28px; }
.field-note p { margin: 4px 0 0; }
.closing { min-height: 69vh; padding: 13vh clamp(22px,7vw,110px); display: grid; grid-template-columns: 1fr minmax(280px,420px); gap: 8vw; align-items: center; background: linear-gradient(90deg,rgba(10,18,12,.76),rgba(10,18,12,.26)); border-top: 1px solid rgba(255,255,255,.18); }
.closing h2 { margin: 0; font-family: "Noto Serif SC", "Songti SC", serif; font-weight: 500; font-size: clamp(38px,5.6vw,80px); line-height: 1.06; letter-spacing: -.06em; }
.closing-action { align-self: end; }
.closing-action > p { color: rgba(255,255,255,.72); line-height: 1.7; }
.saved { min-height: 1.5em; color: #d8ef9c; font-size: 12px; }
.reduced * { scroll-behavior: auto !important; animation: none !important; transition: none !important; }
@media (max-width: 720px) {
  .station { min-height: 300vh; }
  .masthead { height: 64px; padding: 0 18px; grid-template-columns: 1fr auto; }
  .masthead > span { display: none; }
  .demo { font-size: 10px; }
  .visual-field:before { background-position: 62% center; }
  .visual-field:after { background: linear-gradient(180deg,rgba(9,17,11,.72) 0%,rgba(9,17,11,.22) 45%,rgba(9,17,11,.62) 100%), linear-gradient(90deg,rgba(9,17,11,.54),transparent); }
  .hero { min-height: 98vh; padding: 108px 20px 10vh; justify-content: flex-start; }
  .hero h1 { font-size: clamp(50px,16vw,74px); max-width: 5em; }
  .intro { max-width: 22em; font-size: 14px; }
  .photo-note { display: none; }
  .workspace { min-height: 128vh; padding: 34vh 18px 15vh; display: block; }
  .station-card { width: 100%; padding: 22px 18px; }
  .field-note { margin-top: 24px; }
  .closing { min-height: 74vh; padding: 12vh 20px; display: block; }
  .closing-action { margin-top: 42px; }
  .closing h2 { font-size: clamp(42px,13vw,60px); }
}
